public.logic.go:
package main
import("strings";"strconv")
var _=strings.Compare
var _=strconv.Itoa
func solve(x map[string]any) any {out:=[]any{};for _,p:=range x["paths"].([]any){if strings.HasPrefix(p.(string),x["prefix"].(string)){out=append(out,p)}};return out}

public.main.go:
package main
import("encoding/json";"os";"fmt")
func main(){var inputs []map[string]any;if e:=json.Unmarshal([]byte(os.Args[1]),&inputs);e!=nil{panic(e)};out:=[]any{};for _,x:=range inputs{out=append(out,solve(x))};b,e:=json.Marshal(out);if e!=nil{panic(e)};fmt.Println(string(b))}

