package main
import("encoding/json";"testing";"reflect")
func TestPublicContract(t *testing.T){var cases []struct{Input map[string]any;Expected any};_ = cases;var rows [][]json.RawMessage;if e:=json.Unmarshal([]byte(`[[{"paths": ["a/b", "c"], "prefix": "a"}, ["a/b"]], [{"paths": [], "prefix": ""}, []]]`),&rows);e!=nil{t.Fatal(e)};for _,row:=range rows{var input map[string]any;var expected,actual any;json.Unmarshal(row[0],&input);json.Unmarshal(row[1],&expected);b,e:=json.Marshal(solve(input));if e!=nil{t.Fatal(e)};json.Unmarshal(b,&actual);if !reflect.DeepEqual(actual,expected){t.Fatalf("got %v expected %v",actual,expected)}}}
